var t=`0202-gazpacho`;var r=`world-0202`;var n=`ES`;var a=`southern-europe`;var o=4;var l=105;var s={en:`Gazpacho`,ua:`Гаспачо`};var h={en:`A traditional Spain dish made with tomato, cucumber, green bell pepper, garlic. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Іспанія. Основні інгредієнти: помідор, огірок, зелений солодкий перець, часник. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:8,i:[[`tomato`,850,`g`],[`cucumber`,200,`g`],[`green-bell-pepper`,160,`g`],[`garlic`,2,`clove`]]},{en:`Soak the bread in the water, then blend with the chopped vegetables, oil and sherry vinegar until smooth. Season; thin with cold water if needed.`,ua:`Замочіть хліб у воді, збийте з нарізаними овочами, олією та хересним оцтом до гладкості. Приправте, за потреби розведіть холодною водою.`,t:[`mixing`],m:5,i:[[`white-bread`,90,`g`],[`water`,220,`ml`],[`extra-virgin-olive-oil`,65,`ml`],[`sherry-vinegar`,30,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 90 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 90 хвилин.`,t:[`rapid-chilling`],m:90,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`red-bell-pepper`,50,`g`]]}];var p={slug:t,id:r,country:`ES`,region:a,servings:4,minutes:105,title:s,text:h,steps:d};export{n as country,p as default,r as id,l as minutes,a as region,o as servings,t as slug,d as steps,h as text,s as title};